<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Plus, Search, Pencil, Trash2, ChevronLeft, ChevronRight, CalendarDays, Info, ShieldCheck, LoaderCircle } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import StatePanel from '../components/StatePanel.vue'
import AppModal from '../components/AppModal.vue'
import { toast } from '../components/ToastStack.vue'
import { api, allPages, query, encode, type Page, type Row, type Meeting } from '../lib/api'
import { formatTime, display } from '../lib/format'
import { resources, resourceOrder, stateLabel, type AdminField } from '../lib/adminResources'
import { useAsync } from '../lib/useAsync'

const route = useRoute(), { loading, error, run } = useAsync()
const resource = computed(() => resources[String(route.params.resource)] ? String(route.params.resource) : 'sections'), config = computed(() => resources[resource.value]!)
const items = ref<Row[]>([]), page = ref(0), total = ref(0), q = ref(''), size = 15, selected = ref<Row>(), dialogKind = ref(''), busy = ref(false), modalLoading = ref(false), modalError = ref(''), reason = ref(''), enabled = ref(true)
const form = reactive<Record<string, string | number>>({}), lookups = ref<Record<string, Row[]>>({}), prerequisites = ref<{ courseId: string; minGrade: number }[]>([]), meetings = ref<Meeting[]>([])
const editing = computed(() => !!selected.value), frozen = computed(() => editing.value && selected.value?.state !== 'DRAFT' && ['offerings', 'sections'].includes(resource.value)), pages = computed(() => Math.max(1, Math.ceil(total.value / size)))
const fields = computed(() => config.value.fields.filter(field => (!editing.value || !field.createOnly) && (editing.value || !field.editOnly) && !(resource.value === 'users' && field.key === 'studentId' && form.role !== 'STUDENT') && !(resource.value === 'users' && field.key === 'teacherId' && form.role !== 'TEACHER')))
async function load(reset = false) { if (reset) page.value = 0; await run(async () => { const result = await api<Page<Row>>('/admin/' + resource.value + query({ page: page.value, size, q: q.value.trim() })); items.value = result.items; total.value = result.total }) }
watch(resource, () => { q.value = ''; dialogKind.value = ''; void load(true) }, { immediate: true })
function formatCell(row: Row, key: string) { if (key.endsWith('At')) return formatTime(row[key]); if (['state', 'gradeState', 'role'].includes(key)) return stateLabel(row[key]); if (key === 'enabled') return row[key] ? '已启用' : '已停用'; if (key === 'enrolledCount') return `${row.enrolledCount ?? 0} / ${row.capacity ?? 0}`; return display(row[key]) }
function localDate(value: unknown) { if (!value) return ''; const date = new Date(String(value)); if (Number.isNaN(date.getTime())) return ''; return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16) }
async function loadLookups() { const names = [...new Set(config.value.fields.map(field => field.lookup).filter((v): v is string => !!v))]; if (resource.value === 'offerings' && !names.includes('courses')) names.push('courses'); const results = await Promise.all(names.map(async name => [name, await allPages<Row>('/admin/' + name)] as const)); lookups.value = Object.fromEntries(results) }
async function openEdit(row?: Row) { selected.value = row; dialogKind.value = 'edit'; modalError.value = ''; modalLoading.value = true; for (const key of Object.keys(form)) delete form[key]; prerequisites.value = []; meetings.value = []; try { const current = row ? await api<Row>('/admin/' + resource.value + '/' + encode(String(row.id))) : undefined; selected.value = current; await loadLookups(); for (const field of config.value.fields) { const value = current?.[field.key]; if (field.type === 'checkbox') { enabled.value = value !== false; continue } form[field.key] = field.type === 'datetime-local' ? localDate(value) : value == null ? field.type === 'number' ? field.key === 'capacity' ? 30 : field.key === 'credits' ? 3 : field.key === 'creditLimit' ? 30 : 0 : field.options?.[0]?.value || '' : String(value) } if (current?.version != null) form.version = Number(current.version); prerequisites.value = Array.isArray(current?.prerequisites) ? (current!.prerequisites as { courseId: string; minGrade: number }[]).map(p => ({ courseId: p.courseId, minGrade: p.minGrade })) : []; meetings.value = Array.isArray(current?.meetings) ? (current!.meetings as Meeting[]).map(meeting => ({ ...meeting })) : resource.value === 'sections' ? [{ weekday: 1, startPeriod: 1, endPeriod: 2, startWeek: 1, endWeek: 16, room: '' }] : [] } catch (e) { modalError.value = e instanceof Error ? e.message : '记录读取失败' } finally { modalLoading.value = false } }
function fieldDisabled(field: AdminField) { return field.key === 'id' && editing.value || editing.value && resource.value === 'rounds' && (field.key === 'termId' || selected.value?.state !== 'DRAFT' && ['startsAt', 'endsAt', 'withdrawalEndsAt', 'creditLimit'].includes(field.key)) || frozen.value && (resource.value === 'offerings' ? ['courseId', 'termId', 'credits', 'state'].includes(field.key) : ['offeringId', 'teacherId'].includes(field.key)) }
function lookupLabel(name: string, row: Row) { if (name === 'offerings') return `${row.courseTitle || row.courseId} · ${row.termName || row.termId} · ${row.id}`; return `${row.name || row.title || row.displayName || row.id} · ${row.id}` }
function payload() { const body: Record<string, unknown> = {}; for (const field of fields.value) { const value = form[field.key]; if (field.key === 'password' && !value && editing.value) continue; body[field.key] = field.type === 'number' ? Number(value) : field.type === 'checkbox' ? enabled.value : field.type === 'datetime-local' ? (editing.value && selected.value?.state !== 'DRAFT' ? selected.value?.[field.key] : new Date(String(value)).toISOString()) : String(value ?? '').trim() } if (selected.value?.version != null) body.version = selected.value.version; if (resource.value === 'offerings') body.prerequisites = prerequisites.value.map(p => ({ courseId: p.courseId, minGrade: Number(p.minGrade) })); if (resource.value === 'sections') body.meetings = meetings.value.map(m => ({ ...m, weekday: Number(m.weekday), startPeriod: Number(m.startPeriod), endPeriod: Number(m.endPeriod), startWeek: Number(m.startWeek), endWeek: Number(m.endWeek) })); if (resource.value === 'users' && !editing.value) { if (form.role !== 'STUDENT') delete body.studentId; if (form.role !== 'TEACHER') delete body.teacherId } return body }
async function save() { busy.value = true; modalError.value = ''; try { await api('/admin/' + resource.value + (editing.value ? '/' + encode(String(selected.value!.id)) : ''), { method: editing.value ? 'PUT' : 'POST', body: payload() }); toast(`${config.value.singular}${editing.value ? '已更新' : '已创建'}。`); dialogKind.value = ''; if ('password' in form) form.password = ''; await load() } catch (e) { modalError.value = e instanceof Error ? e.message : '保存失败' } finally { busy.value = false } }
function openAction(kind: string, row: Row) { selected.value = row; reason.value = ''; modalError.value = ''; dialogKind.value = kind }
async function submitAction() { if (!selected.value) return; busy.value = true; modalError.value = ''; try { if (dialogKind.value === 'delete') await api('/admin/' + resource.value + '/' + encode(String(selected.value.id)), { method: 'DELETE' }); else await api('/admin/sections/' + encode(String(selected.value.id)) + '/reopen-grades', { method: 'POST', body: { reason: reason.value.trim(), version: selected.value.version } }); toast(dialogKind.value === 'delete' ? '记录已删除。' : '成绩册已重新开放，更正原因已记录。'); dialogKind.value = ''; await load() } catch (e) { modalError.value = e instanceof Error ? e.message : '操作失败' } finally { busy.value = false } }
function paginate(delta: number) { page.value += delta; void load() }
</script>
<template><PageHeading eyebrow="GOOD TEACHING STARTS WITH GOOD ORDER" title="教学管理" :description="config.description"><button class="button" @click="openEdit()"><Plus :size="15"/>新增{{ config.singular }}</button></PageHeading><nav class="admin-resource-tabs" aria-label="管理对象"><RouterLink v-for="name in resourceOrder" :key="name" :to="'/admin/manage/' + name" :class="{ 'router-link-active': resource === name }">{{ resources[name]!.title }}</RouterLink></nav><section class="card"><div class="card-header"><div><h2>{{ config.title }}</h2><p>共 {{ total }} 条记录 · 修改时检查最新版本，重要变更保留记录</p></div><form class="search-field" @submit.prevent="load(true)"><Search :size="14"/><input v-model="q" :aria-label="'搜索' + config.singular" placeholder="搜索名称或编号"><button type="submit" class="icon-button" aria-label="执行搜索" style="width:20px;height:20px"><ChevronRight :size="14"/></button></form></div><StatePanel v-if="loading" loading/><StatePanel v-else-if="error" :error="error" @retry="load()"/><StatePanel v-else-if="!items.length" :title="q ? '没有匹配的记录' : `还没有${config.singular}记录`" description="可以调整搜索条件，或新增一条完整的教学记录。"/><div v-else class="table-wrap"><table><caption class="sr-only">{{ config.title }}</caption><thead><tr><th v-for="column in config.columns" :key="column.key">{{ column.label }}</th><th>管理操作</th></tr></thead><tbody><tr v-for="row in items" :key="String(row.id)"><td v-for="(column, index) in config.columns" :key="column.key"><template v-if="['state', 'gradeState', 'role'].includes(column.key)"><span class="tag" :class="row[column.key] === 'DRAFT' || row[column.key] === 'ARCHIVED' || row[column.key] === 'CLOSED' ? 'tag-neutral' : ''">{{ formatCell(row, column.key) }}</span></template><template v-else-if="index === 0"><strong>{{ formatCell(row, column.key) }}</strong><small v-if="column.key !== 'id' && resource !== 'users'">{{ row.id }}</small></template><template v-else>{{ formatCell(row, column.key) }}</template></td><td><div class="row-actions"><button class="text-button" @click="openEdit(row)"><Pencil :size="11"/>编辑</button><button v-if="resource === 'sections' && row.gradeState === 'PUBLISHED'" class="text-button" @click="openAction('reopen', row)">成绩更正</button><button v-if="resource !== 'users'" class="text-button text-red" @click="openAction('delete', row)"><Trash2 :size="11"/>删除</button></div></td></tr></tbody></table></div><div v-if="total" class="card-footer"><span>第 {{ page + 1 }} 页，共 {{ pages }} 页</span><div class="pagination"><button aria-label="上一页" :disabled="page === 0 || loading" @click="paginate(-1)"><ChevronLeft :size="14"/></button><button aria-label="下一页" :disabled="page + 1 >= pages || loading" @click="paginate(1)"><ChevronRight :size="14"/></button></div></div></section><AppModal :open="!!dialogKind" :title="dialogKind === 'edit' ? `${editing ? '编辑' : '新增'}${config.singular}` : dialogKind === 'delete' ? `删除${config.singular}` : '重新开放成绩册'" :wide="dialogKind === 'edit' && ['sections', 'offerings', 'rounds'].includes(resource)" :busy="busy" @close="dialogKind = ''"><div v-if="modalError" class="error-inline" role="alert">{{ modalError }}</div><StatePanel v-if="modalLoading" loading/><form v-else-if="dialogKind === 'edit'" id="admin-resource-form" @submit.prevent="save"><div v-if="frozen" class="notice-banner"><Info :size="15"/><span>{{ resource === 'offerings' ? '此开课计划已发布，学分与先修要求已冻结。' : '此教学班已发布，教师和课表安排已冻结。调整容量时不能低于实际选课人数。' }}</span></div><div class="form-grid"><label v-for="field in fields" :key="field.key" class="field" :class="{ 'field-full': field.wide, 'field-checkbox': field.type === 'checkbox' }"><template v-if="field.type !== 'checkbox'">{{ field.label }}</template><textarea v-if="field.type === 'textarea'" v-model="form[field.key]" :required="!field.optional" maxlength="2000" :disabled="fieldDisabled(field) || busy"/><select v-else-if="field.type === 'select'" v-model="form[field.key]" :required="!field.optional" :disabled="fieldDisabled(field) || busy"><option value="" disabled>请选择{{ field.label }}</option><template v-if="field.lookup"><option v-for="row in lookups[field.lookup] || []" :key="String(row.id)" :value="String(row.id)">{{ lookupLabel(field.lookup, row) }}</option></template><option v-for="option in field.options || []" :key="option.value" :value="option.value">{{ option.label }}</option></select><input v-else-if="field.type === 'checkbox'" v-model="enabled" type="checkbox" :disabled="busy"><input v-else v-model="form[field.key]" :type="field.type || 'text'" :min="field.min" :max="field.max" :step="field.type === 'number' ? 1 : undefined" :minlength="field.key === 'password' ? 10 : undefined" :maxlength="field.type === 'password' ? 200 : 120" :autocomplete="field.type === 'password' ? 'new-password' : 'off'" :required="!field.optional || (field.key === 'password' && !editing)" :readonly="field.key === 'id' && editing" :disabled="fieldDisabled(field) && field.key !== 'id' || busy"><template v-if="field.type === 'checkbox'">{{ field.label }}</template><small v-if="field.help">{{ field.help }}</small></label></div><template v-if="resource === 'offerings'"><div class="info-divider"/><div class="row-between"><h3>先修课程要求</h3><button class="text-button" type="button" :disabled="frozen || busy" @click="prerequisites.push({ courseId: '', minGrade: 60 })"><Plus :size="12"/>添加先修课</button></div><p class="muted mt-12" style="font-size:10px">仅正式发布的通过成绩计入资格。没有先修要求时可以留空。</p><div v-for="(prerequisite, i) in prerequisites" :key="i" class="form-grid mt-20"><label class="field">先修课程<select v-model="prerequisite.courseId" :disabled="frozen || busy" required><option value="" disabled>请选择课程</option><option v-for="course in (lookups.courses || []).filter(c => c.id !== form.courseId)" :key="String(course.id)" :value="String(course.id)">{{ course.title }} · {{ course.id }}</option></select></label><div class="row"><label class="field spacer">最低成绩<input v-model.number="prerequisite.minGrade" type="number" min="0" max="100" step="0.01" :disabled="frozen || busy" required></label><button type="button" class="icon-button" style="align-self:end;margin-bottom:5px" :disabled="frozen || busy" :aria-label="'删除第' + (i + 1) + '条先修要求'" @click="prerequisites.splice(i, 1)"><Trash2 :size="15"/></button></div></div></template><template v-if="resource === 'sections'"><div class="info-divider"/><div class="row-between"><h3 class="row"><CalendarDays :size="16"/>上课时间与教室</h3><button type="button" class="text-button" :disabled="frozen || busy" @click="meetings.push({ weekday: 1, startPeriod: 1, endPeriod: 2, startWeek: 1, endWeek: 16, room: '' })"><Plus :size="12"/>添加时段</button></div><div v-for="(meeting, i) in meetings" :key="i" class="detail-summary mt-20"><div class="row-between mb-20"><strong style="font-size:11px">上课时段 {{ i + 1 }}</strong><button type="button" class="icon-button" :disabled="frozen || busy" :aria-label="'删除第' + (i + 1) + '个时段'" @click="meetings.splice(i, 1)"><Trash2 :size="14"/></button></div><div class="form-grid"><label class="field">星期<select v-model.number="meeting.weekday" :disabled="frozen || busy" required><option v-for="(day, index) in ['星期一', '星期二', '星期三', '星期四', '星期五', '星期六', '星期日']" :key="day" :value="index + 1">{{ day }}</option></select></label><label class="field">上课教室<input v-model="meeting.room" :disabled="frozen || busy" required maxlength="100" placeholder="例如：教101"></label><label class="field">开始节次<input v-model.number="meeting.startPeriod" type="number" min="1" max="14" :disabled="frozen || busy" required></label><label class="field">结束节次<input v-model.number="meeting.endPeriod" type="number" :min="meeting.startPeriod" max="14" :disabled="frozen || busy" required></label><label class="field">开始教学周<input v-model.number="meeting.startWeek" type="number" min="1" max="30" :disabled="frozen || busy" required></label><label class="field">结束教学周<input v-model.number="meeting.endWeek" type="number" :min="meeting.startWeek" max="30" :disabled="frozen || busy" required></label></div></div></template></form><template v-else-if="dialogKind === 'delete'"><p class="modal-description">确定删除 {{ selected?.name || selected?.title || selected?.courseTitle || selected?.id }}？</p><p class="preview-alert">存在关联教学数据或历史记录时，系统会拒绝删除。已发布的教学安排请优先归档，保留教学历史。</p></template><form v-else-if="dialogKind === 'reopen'" id="reopen-grades-form" @submit.prevent="submitAction"><p class="modal-description">为 {{ selected?.courseTitle }}（{{ selected?.id }}）开放成绩更正。</p><div class="notice-banner"><ShieldCheck :size="16"/><span>学生在更正期间仍看到上次正式成绩。教师重新发布后，新结果才会同步。更正原因会写入操作记录。</span></div><label class="field">更正原因<textarea v-model="reason" required minlength="5" maxlength="500" placeholder="请说明本次成绩更正的真实原因"/></label></form><template #footer><button class="button button-secondary" :disabled="busy" @click="dialogKind = ''">取消</button><button v-if="dialogKind === 'edit'" class="button" type="submit" form="admin-resource-form" :disabled="busy || modalLoading"><LoaderCircle v-if="busy" :size="14" class="spin"/>{{ busy ? '正在保存…' : '保存' }}</button><button v-else-if="dialogKind === 'reopen'" class="button" type="submit" form="reopen-grades-form" :disabled="busy">确认开放更正</button><button v-else class="button button-danger" :disabled="busy" @click="submitAction">确认删除</button></template></AppModal></template>
